from produire import produire,paras,steps,table
parts=[
('La {spondylodiscite cervicale} est une infection du disque et des vertèbres adjacentes. Elle peut s’étendre aux tissus voisins et au canal rachidien. Une compression médullaire constitue une urgence.',paras('La leçon vise surtout l’infection bactérienne pyogène. Une tuberculose, une infection fongique ou une infection sur matériel exige une démarche adaptée.', 'Le site cervical rend particulièrement préoccupants déficit des membres et menace médullaire. La douleur peut être attribuée à tort à une affection dégénérative.')),
('Le {terrain oriente la suspicion}. Bactériémie, infection récente, immunosuppression ou geste rachidien augmentent le risque. La fièvre peut manquer.',paras('Rechercher diabète, fragilité, usage de drogues injectables, cathéter, plaie et chirurgie ou infiltration récente. L’absence de facteur retrouvé n’exclut pas l’infection.', 'L’Inselspital souligne les portes d’entrée distantes, notamment cutanées, buccales ou respiratoires, ainsi que l’infection après chirurgie. Le matériel implanté modifie la recherche microbiologique et la stratégie.')),
('Le {mécanisme associe infection et destruction}. La dissémination sanguine est une voie fréquente. L’atteinte des plateaux et du disque peut déstabiliser le rachis.',paras('Une collection épidurale peut comprimer moelle ou racines. Une extension paravertébrale peut accompagner les lésions osseuses.', 'Le contrôle de l’infection ne suffit pas toujours à corriger une instabilité déjà constituée. Décompression, drainage et stabilisation répondent à des problèmes complémentaires.')),
('Le {tri recherche sepsis et atteinte neurologique}. Déficit nouveau, trouble de marche ou dysfonction sphinctérienne impose une évaluation urgente. Une douleur persistante avec terrain infectieux mérite un bilan rapide même sans fièvre.',paras('En cas de sepsis, choc ou déficit progressif, adresser immédiatement à l’hôpital et contacter les équipes compétentes. Ne pas différer les soins urgents en attendant une biopsie élective.', 'Documenter l’examen neurologique initial. Éviter manipulations et mobilisation forcée si une destruction ou une instabilité est suspectée.')),
('L’{anamnèse cherche infection et évolution}. Préciser douleur, durée, réveils nocturnes et limitation fonctionnelle. Rechercher fièvre, frissons, amaigrissement et antibiotiques déjà reçus.',paras('Interroger sur bactériémie récente, endocardite, infection cutanée ou urinaire et procédure rachidienne. Un traitement antibiotique préalable peut diminuer le rendement des cultures.', 'Demander irradiation, faiblesse, maladresse, troubles de marche et troubles urinaires. Une douleur accentuée par le mouvement ne suffit pas à la classer comme cervicalgie commune.')),
('L’{examen associe rachis, neurologie et état général}. Évaluer constantes et signes de sepsis. Rechercher douleur focale, déficit, signes médullaires et porte d’entrée.',paras('Examiner les quatre membres, les réflexes et la marche si elle est sûre. Des symptômes dans les jambes peuvent provenir d’une lésion cervicale.', 'Inspecter peau, plaies, dispositifs et cicatrices. Une raideur douloureuse n’identifie pas le germe et ne distingue pas seule infection, fracture ou inflammation microcristalline.')),
('L’{approche syndromique situe la menace}. Douleur rachidienne et inflammation font évoquer l’infection. Les signes radiculaires ou médullaires recherchent une extension compressive.',table(['Association','Conséquence'],[['Douleur et bactériémie.','Rechercher un foyer vertébral et d’autres localisations.'],['Douleur et déficit médullaire.','IRM urgente et avis chirurgical.'],['Inflammation sans fièvre.','Infection toujours possible ; discuter aussi cause inflammatoire ou tumorale.'],['Chirurgie ou matériel récents.','Parcours spécifique avec prélèvements adaptés et avis infectiologique.']])) ,
('Le {diagnostic combine imagerie et identification du germe}. L’IRM est l’examen de référence. Les hémocultures précoces peuvent orienter le traitement.',paras('Rechercher atteinte discale et vertébrale, collections et compression. Le scanner complète l’évaluation des destructions osseuses et peut guider une biopsie.', 'Un syndrome inflammatoire soutient la suspicion sans suffire à la confirmer. Une radiographie normale au début ne permet pas d’écarter la maladie.')),
('Les {examens doivent préserver la documentation sans retarder une urgence}. Prélever les hémocultures avant antibiotiques lorsque cela est immédiatement possible. Une biopsie est discutée si la microbiologie reste négative.',paras('Chez un patient stable sans sepsis ni complication neurologique, organiser les prélèvements avant le traitement avec l’infectiologue. Une biopsie guidée ou un prélèvement opératoire doit permettre microbiologie et analyse histologique.', 'En cas de sepsis ou de menace neurologique, réaliser rapidement les prélèvements accessibles puis traiter ; ne pas attendre une biopsie programmée. Rechercher porte d’entrée et foyers associés, notamment une endocardite selon le germe et le contexte.')),
('L’{algorithme associe documentation et contrôle du foyer}. L’urgence clinique détermine le calendrier. L’imagerie seule ne choisit pas l’antibiotique.',steps('Identifier sepsis, déficit et instabilité ; hospitaliser sans délai si présents.', 'Hémocultures et bilan biologique, puis IRM cervicale ; étendre l’étude selon symptômes et contexte.', 'Si stable, obtenir documentation microbiologique adaptée avant antibiothérapie.', 'Si urgence, antibiothérapie après prélèvements rapides et avis chirurgical sans attendre une biopsie différée.', 'Adapter au germe, contrôler le foyer et surveiller clinique, biologie et stabilité.')),
('La {prise en charge suisse est multidisciplinaire}. Infectiologue et équipe du rachis coordonnent antibiothérapie et éventuel geste. La durée dépend du germe, du foyer et de l’évolution.',paras('L’Inselspital décrit une antibiothérapie ciblée et, selon les lésions, drainage, décompression et stabilisation. Le consensus européen recommande une stratégie probabiliste définie avec les spécialistes selon terrain et écologie locale.', 'Un déficit médullaire, un abcès compressif, une instabilité ou un échec de traitement peut nécessiter une chirurgie. Une valeur inflammatoire élevée isolée ne décide pas à elle seule du moment opératoire.', 'Il n’existe pas de schéma antibiotique universel pour cette leçon. La dose suisse de chaque spécialité, les adaptations rénales et les interactions doivent être vérifiées après choix du traitement. Les durées de six ou douze semaines discutées dans le consensus dépendent des formes simples ou compliquées ; elles ne sont pas interchangeables ni automatiques.')),
('Le {suivi recherche rechute et séquelles mécaniques}. Évaluer douleur, neurologie, mobilité et paramètres inflammatoires. La rééducation dépend de la stabilité et des consignes de l’équipe.',paras('Surveiller tolérance et observance de l’antibiothérapie ainsi que la porte d’entrée. Une aggravation clinique ou neurologique impose une nouvelle évaluation rapide.', 'Des anomalies IRM peuvent persister après contrôle de l’infection. Le suivi ne repose donc pas sur la disparition de toute image ; la répétition de l’imagerie répond à une question clinique ou mécanique.')),
('Le {point clé} est de suspecter l’infection même sans fièvre. Prélever avant antibiotiques améliore la documentation chez le patient stable. Sepsis et menace médullaire imposent de traiter sans attendre une biopsie différée.',paras('Préserver simultanément trois objectifs : identifier le germe, contrôler le foyer infectieux et protéger la moelle et la stabilité du rachis.'))]
quiz=[('La fièvre est-elle obligatoire ?','Non.'),('Une douleur au mouvement exclut-elle l’infection ?','Non.'),('Quelles structures sont atteintes ?','Le disque et les vertèbres adjacentes.'),('Pourquoi rechercher un déficit des jambes ?','Une atteinte cervicale peut comprimer la moelle.'),('Quel examen est central ?','L’IRM.'),('Que recherche le scanner en complément ?','Les destructions osseuses et les éléments utiles au geste.'),('Quand prélever les hémocultures ?','Avant antibiotiques si immédiatement possible.'),('Une biopsie est-elle nécessaire dans tous les cas ?','Non, selon documentation sanguine, imagerie et contexte.'),('Attendre une biopsie en cas de choc ?','Non.'),('Une complication neurologique change-t-elle le calendrier ?','Oui, elle impose une prise en charge urgente.'),('Faut-il chercher une porte d’entrée ?','Oui, ainsi que des foyers associés selon le contexte.'),('Existe-t-il un antibiotique universel ?','Non.'),('La chirurgie ne sert-elle qu’à prélever ?','Non, elle peut drainer, décomprimer et stabiliser.'),('Une image IRM persistante prouve-t-elle seule l’échec ?','Non, confronter à la clinique et à la biologie.')]
produire(8,parts,quiz,(4,7,22))
